class Point {
  int x, y;
  Point(int x, int y) { this.x = x; this.y = y; }
}

public class Main {
  public static void main(String[] args) {
    Set<Point> visited = new HashSet<>();
    visited.add(new Point(1, 2));
    boolean seen = visited.contains(new Point(1, 2));
    System.out.println(seen);
  }
}
